  insert into public.profiles (id, display_name, privacy_accepted_at)
insert into public.categories (id, name, description, construct, practice, sort_order, active) values ('logico', 'Raciocínio lógico', 'Organizar informações, comparar relações e identificar a única configuração compatível com todas as condições.', 'Raciocínio sequencial e relacional (componente de raciocínio fluido)', '["Resolver problemas de ordenação com tabelas de possibilidades","Puzzles de verdade/mentira anotando cada hipótese","Jogos de lógica como Sudoku e nonogramas"]'::jsonb, 1, true) on conflict (id) do nothing;
insert into public.categories (id, name, description, construct, practice, sort_order, active) values ('abstrato', 'Raciocínio abstrato', 'Inferir regras não verbais em matrizes de figuras e aplicá-las para completar o padrão.', 'Indução de regras em material figural (raciocínio fluido, Gf)', '["Descrever em palavras cada regra que muda em linhas e colunas","Separar atributos: forma, quantidade, preenchimento e rotação","Praticar matrizes de figuras de domínio público"]'::jsonb, 2, true) on conflict (id) do nothing;
insert into public.categories (id, name, description, construct, practice, sort_order, active) values ('padroes', 'Reconhecimento de padrões', 'Identificar regularidades em sequências de letras, símbolos e figuras.', 'Indução de regularidades seriais', '["Converter letras em posições numéricas (A = 1, B = 2…)","Procurar duas regras alternadas na mesma sequência","Criar suas próprias sequências e testá-las com outras pessoas"]'::jsonb, 3, true) on conflict (id) do nothing;
insert into public.categories (id, name, description, construct, practice, sort_order, active) values ('numerico', 'Sequências numéricas', 'Descobrir a regra que gera uma série numérica e prever o próximo termo.', 'Indução quantitativa (raciocínio fluido quantitativo)', '["Calcular as diferenças entre termos e as diferenças das diferenças","Testar razões (multiplicação/divisão) quando as diferenças crescem rápido","Verificar se há duas séries intercaladas"]'::jsonb, 4, true) on conflict (id) do nothing;
insert into public.categories (id, name, description, construct, practice, sort_order, active) values ('espacial', 'Relações espaciais', 'Manipular mentalmente orientação, rotação, reflexão e estrutura tridimensional.', 'Visualização e rotação mental (habilidade visuoespacial, Gv)', '["Montar e desmontar planificações de cubos em papel","Jogos de encaixe e rotação de peças","Desenhar uma figura e prever como fica após girar ou espelhar"]'::jsonb, 5, true) on conflict (id) do nothing;
insert into public.categories (id, name, description, construct, practice, sort_order, active) values ('verbal', 'Analogias verbais', 'Reconhecer a relação entre dois conceitos e encontrar um par com a mesma relação.', 'Raciocínio analógico com conhecimento verbal (envolve conhecimento cristalizado, Gc)', '["Nomear explicitamente a relação do primeiro par antes de olhar as opções","Leitura variada para ampliar vocabulário","Classificar relações: parte–todo, ferramenta–função, oposição, causa–efeito"]'::jsonb, 6, true) on conflict (id) do nothing;
insert into public.categories (id, name, description, construct, practice, sort_order, active) values ('deducao', 'Dedução lógica', 'Avaliar o que se segue necessariamente de premissas, distinguindo conclusões válidas de plausíveis.', 'Raciocínio dedutivo (silogismos e condicionais)', '["Representar premissas com diagramas de Venn","Estudar falácias formais: afirmar o consequente e negar o antecedente","Reescrever condicionais na forma contrapositiva"]'::jsonb, 7, true) on conflict (id) do nothing;
insert into public.categories (id, name, description, construct, practice, sort_order, active) values ('problemas', 'Resolução de problemas', 'Modelar situações cotidianas e encontrar estratégias eficientes de solução.', 'Resolução de problemas e planejamento', '["Simular casos pequenos antes de generalizar","Desenhar o problema em um esquema","Conferir a resposta voltando ao enunciado"]'::jsonb, 8, true) on conflict (id) do nothing;
insert into public.categories (id, name, description, construct, practice, sort_order, active) values ('memoria', 'Memória de trabalho', 'Manter e manipular informações por poucos segundos depois que elas deixam de estar visíveis.', 'Memória de trabalho (armazenamento e manipulação breve, Gwm)', '["Repetir sequências de dígitos na ordem inversa","Agrupar itens em blocos de 3 ou 4 (chunking)","Exercícios do tipo n-back, sabendo que o ganho tende a ser específico da tarefa"]'::jsonb, 9, true) on conflict (id) do nothing;
insert into public.categories (id, name, description, construct, practice, sort_order, active) values ('quantitativo', 'Raciocínio quantitativo', 'Aplicar proporções, porcentagens, médias e taxas para resolver problemas numéricos.', 'Raciocínio quantitativo aplicado (Gq/Gf-quantitativo)', '["Revisar porcentagens compostas (aumentos e descontos sucessivos)","Resolver problemas de taxa com a fórmula trabalho = taxa × tempo","Estimar a ordem de grandeza da resposta antes de calcular"]'::jsonb, 10, true) on conflict (id) do nothing;
insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('abs-001', 1, 'pt-BR', 'abstrato', 1, 'matrix', 'Observe a matriz e escolha a figura que completa a célula vazia.', null, '{"matrix":[{"shape":"circle","fill":"outline","rotation":0,"mirror":false,"count":1},{"shape":"circle","fill":"outline","rotation":0,"mirror":false,"count":2},{"shape":"circle","fill":"outline","rotation":0,"mirror":false,"count":3},{"shape":"square","fill":"outline","rotation":0,"mirror":false,"count":1},{"shape":"square","fill":"outline","rotation":0,"mirror":false,"count":2},{"shape":"square","fill":"outline","rotation":0,"mirror":false,"count":3},{"shape":"triangle","fill":"outline","rotation":0,"mirror":false,"count":1},{"shape":"triangle","fill":"outline","rotation":0,"mirror":false,"count":2},null]}'::jsonb, 'a', 'Cada linha mantém a mesma forma e a quantidade aumenta de 1 a 3 da esquerda para a direita. Na terceira linha (triângulos), falta a figura com 3 triângulos.', 'Regra de progressão quantitativa com forma constante por linha.', 40, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Regras verificadas por linha e por coluna; cada distrator viola ao menos uma regra. Itens originais construídos com regras do tipo descrito por Carpenter, Just e Shell (1990). Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
