insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('abs-002', 1, 'pt-BR', 'abstrato', 1, 'matrix', 'Observe a matriz e escolha a figura que completa a célula vazia.', null, '{"matrix":[{"shape":"square","fill":"outline","rotation":0,"mirror":false,"count":1},{"shape":"square","fill":"striped","rotation":0,"mirror":false,"count":1},{"shape":"square","fill":"solid","rotation":0,"mirror":false,"count":1},{"shape":"circle","fill":"outline","rotation":0,"mirror":false,"count":1},{"shape":"circle","fill":"striped","rotation":0,"mirror":false,"count":1},{"shape":"circle","fill":"solid","rotation":0,"mirror":false,"count":1},{"shape":"diamond","fill":"outline","rotation":0,"mirror":false,"count":1},{"shape":"diamond","fill":"striped","rotation":0,"mirror":false,"count":1},null]}'::jsonb, 'c', 'A forma é constante em cada linha; o preenchimento segue a ordem vazado → listrado → sólido em cada linha. Falta o losango sólido.', 'Duas regras independentes e simples (forma por linha, preenchimento por coluna).', 40, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Regras verificadas por linha e por coluna; cada distrator viola ao menos uma regra. Itens originais construídos com regras do tipo descrito por Carpenter, Just e Shell (1990). Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
