insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('abs-003', 1, 'pt-BR', 'abstrato', 2, 'matrix', 'Observe a matriz e escolha a figura que completa a célula vazia.', null, '{"matrix":[{"shape":"circle","fill":"solid","rotation":0,"mirror":false,"count":1},{"shape":"square","fill":"outline","rotation":0,"mirror":false,"count":1},{"shape":"triangle","fill":"striped","rotation":0,"mirror":false,"count":1},{"shape":"square","fill":"striped","rotation":0,"mirror":false,"count":1},{"shape":"triangle","fill":"solid","rotation":0,"mirror":false,"count":1},{"shape":"circle","fill":"outline","rotation":0,"mirror":false,"count":1},{"shape":"triangle","fill":"outline","rotation":0,"mirror":false,"count":1},{"shape":"circle","fill":"striped","rotation":0,"mirror":false,"count":1},null]}'::jsonb, 'b', 'Cada linha e cada coluna contém exatamente uma vez cada forma (círculo, quadrado, triângulo) e cada preenchimento (sólido, vazado, listrado). Na última linha faltam o quadrado e o preenchimento sólido; a terceira coluna confirma: já tem listrado e vazado.', 'Regra de distribuição de três valores (quadrado latino) em dois atributos.', 60, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Regras verificadas por linha e por coluna; cada distrator viola ao menos uma regra. Itens originais construídos com regras do tipo descrito por Carpenter, Just e Shell (1990). Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
