insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('abs-004', 1, 'pt-BR', 'abstrato', 2, 'matrix', 'Observe a matriz e escolha a figura que completa a célula vazia.', null, '{"matrix":[{"shape":"arrow","fill":"solid","rotation":0,"mirror":false,"count":1},{"shape":"arrow","fill":"solid","rotation":45,"mirror":false,"count":1},{"shape":"arrow","fill":"solid","rotation":90,"mirror":false,"count":1},{"shape":"arrow","fill":"solid","rotation":90,"mirror":false,"count":1},{"shape":"arrow","fill":"solid","rotation":135,"mirror":false,"count":1},{"shape":"arrow","fill":"solid","rotation":180,"mirror":false,"count":1},{"shape":"arrow","fill":"solid","rotation":180,"mirror":false,"count":1},{"shape":"arrow","fill":"solid","rotation":225,"mirror":false,"count":1},null]}'::jsonb, 'c', 'Da esquerda para a direita, a seta gira 45° no sentido horário. Cada linha começa onde a linha anterior terminou. A terceira linha vai de 180° (para baixo) a 225°; a próxima posição é 270° (seta para a esquerda).', 'Regra de rotação constante com encadeamento entre linhas.', 60, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Regras verificadas por linha e por coluna; cada distrator viola ao menos uma regra. Itens originais construídos com regras do tipo descrito por Carpenter, Just e Shell (1990). Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
