insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('abs-005', 1, 'pt-BR', 'abstrato', 2, 'matrix', 'Observe a matriz e escolha a figura que completa a célula vazia.', null, '{"matrix":[{"shape":"star","fill":"solid","rotation":0,"mirror":false,"count":1},{"shape":"star","fill":"solid","rotation":0,"mirror":false,"count":2},{"shape":"star","fill":"solid","rotation":0,"mirror":false,"count":3},{"shape":"hexagon","fill":"solid","rotation":0,"mirror":false,"count":2},{"shape":"hexagon","fill":"solid","rotation":0,"mirror":false,"count":1},{"shape":"hexagon","fill":"solid","rotation":0,"mirror":false,"count":3},{"shape":"pentagon","fill":"solid","rotation":0,"mirror":false,"count":2},{"shape":"pentagon","fill":"solid","rotation":0,"mirror":false,"count":2},null]}'::jsonb, 'd', 'Em cada linha, a quantidade da terceira coluna é a soma das duas primeiras (1 + 2 = 3; 2 + 1 = 3). Na última linha: 2 + 2 = 4 pentágonos.', 'Regra aditiva; a segunda linha (2, 1, 3) descarta a hipótese de simples progressão 1, 2, 3.', 60, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Regras verificadas por linha e por coluna; cada distrator viola ao menos uma regra. Itens originais construídos com regras do tipo descrito por Carpenter, Just e Shell (1990). Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
