insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('abs-006', 1, 'pt-BR', 'abstrato', 3, 'matrix', 'Observe a matriz e escolha a figura que completa a célula vazia.', null, '{"matrix":[{"shape":"circle","fill":"outline","rotation":0,"mirror":false,"count":1},{"shape":"circle","fill":"solid","rotation":0,"mirror":false,"count":2},{"shape":"circle","fill":"striped","rotation":0,"mirror":false,"count":3},{"shape":"square","fill":"striped","rotation":0,"mirror":false,"count":2},{"shape":"square","fill":"outline","rotation":0,"mirror":false,"count":3},{"shape":"square","fill":"solid","rotation":0,"mirror":false,"count":1},{"shape":"triangle","fill":"solid","rotation":0,"mirror":false,"count":3},{"shape":"triangle","fill":"striped","rotation":0,"mirror":false,"count":1},null]}'::jsonb, 'c', 'Três regras simultâneas: a forma é constante em cada linha; as quantidades 1, 2 e 3 aparecem uma vez em cada linha e coluna; os preenchimentos vazado, sólido e listrado também aparecem uma vez em cada linha e coluna. Na última célula: triângulo, quantidade 2 (falta na linha e na coluna) e preenchimento vazado (falta na linha e na coluna).', 'Três atributos combinados; cada distrator viola exatamente um atributo.', 90, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Regras verificadas por linha e por coluna; cada distrator viola ao menos uma regra. Itens originais construídos com regras do tipo descrito por Carpenter, Just e Shell (1990). Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
