insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('abs-007', 1, 'pt-BR', 'abstrato', 3, 'matrix', 'Observe a matriz e escolha a figura que completa a célula vazia.', null, '{"matrix":[{"shape":"arrow","fill":"solid","rotation":0,"mirror":false,"count":1},{"shape":"arrow","fill":"solid","rotation":90,"mirror":false,"count":1},{"shape":"arrow","fill":"solid","rotation":180,"mirror":false,"count":1},{"shape":"arrow","fill":"solid","rotation":90,"mirror":false,"count":2},{"shape":"arrow","fill":"solid","rotation":180,"mirror":false,"count":2},{"shape":"arrow","fill":"solid","rotation":270,"mirror":false,"count":2},{"shape":"arrow","fill":"solid","rotation":180,"mirror":false,"count":3},{"shape":"arrow","fill":"solid","rotation":270,"mirror":false,"count":3},null]}'::jsonb, 'a', 'A quantidade de setas é constante em cada linha e aumenta de linha para linha (1, 2, 3). A direção gira 90° no sentido horário a cada coluna, e cada linha começa 90° adiante da anterior. Na última linha: 180° → 270° → 360° = 0° (seta para cima), com 3 setas.', 'Dois atributos (quantidade por linha, rotação por coluna com deslocamento) e retorno cíclico a 0°.', 90, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Regras verificadas por linha e por coluna; cada distrator viola ao menos uma regra. Itens originais construídos com regras do tipo descrito por Carpenter, Just e Shell (1990). Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
