insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('ded-005', 1, 'pt-BR', 'deducao', 2, 'text', 'Avalie o argumento: "Se chove, a rua fica molhada. A rua está molhada. Logo, choveu." Esse argumento é:', null, null, 'c', 'A forma ''Se P então Q; Q; logo P'' é a falácia de afirmação do consequente: a rua pode estar molhada por outro motivo (uma mangueira, por exemplo).', 'Identificação de falácia formal clássica.', 55, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Validade conferida por diagramas de Venn e contraexemplos para cada distrator. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
