insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('ded-006', 1, 'pt-BR', 'deducao', 2, 'text', 'Qual é a negação lógica da frase "Todos os funcionários chegaram cedo"?', null, null, 'b', 'A negação de ''todos são P'' é ''existe pelo menos um que não é P''. ''Nenhum chegou cedo'' é uma afirmação mais forte do que a negação.', 'Negação de quantificador universal.', 45, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Validade conferida por diagramas de Venn e contraexemplos para cada distrator. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
