insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('esp-001', 1, 'pt-BR', 'espacial', 1, 'text', 'Você está de frente para o norte. Gira 90° para a sua direita e, em seguida, gira 180°. Para que direção está voltado agora?', null, null, 'd', 'Girando 90° à direita a partir do norte, você fica voltado para o leste. Girando 180°, passa a olhar para o oeste.', 'Orientação espacial com composição de rotações.', 30, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Transformações geométricas conferidas; a figura F não possui simetria, então as 8 orientações (4 rotações × espelhamento) são distintas. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
