insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('esp-002', 1, 'pt-BR', 'espacial', 1, 'text', 'Imagine a letra minúscula "b" refletida em um espelho colocado ao lado dela (a imagem fica invertida da esquerda para a direita). Com qual letra a imagem refletida se parece?', null, null, 'b', 'A reflexão esquerda–direita leva a haste do lado esquerdo para o direito, mantendo-a para cima: "b" vira "d". (A reflexão de cima para baixo levaria a "p".)', 'Reflexão em eixo vertical; distratores correspondem a outras transformações.', 30, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Transformações geométricas conferidas; a figura F não possui simetria, então as 8 orientações (4 rotações × espelhamento) são distintas. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
