insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('esp-003', 1, 'pt-BR', 'espacial', 2, 'figure_choice', 'Qual alternativa mostra a figura-modelo girada 90° no sentido horário?', null, '{"model":{"shape":"fshape","fill":"solid","rotation":0,"mirror":false,"count":1}}'::jsonb, 'b', 'Girar 90° no sentido horário leva a haste vertical do F para a posição horizontal, com os braços voltados para baixo. A alternativa espelhada tem a mesma inclinação, mas os braços estão do lado oposto.', 'Rotação mental 2D com distrator espelhado (paradigma de Shepard e Metzler adaptado ao plano).', 45, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Transformações geométricas conferidas; a figura F não possui simetria, então as 8 orientações (4 rotações × espelhamento) são distintas. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
