insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('esp-004', 1, 'pt-BR', 'espacial', 2, 'figure_choice', 'Apenas uma alternativa mostra a figura-modelo somente GIRADA (sem espelhamento). As demais são versões espelhadas. Qual é ela?', null, '{"model":{"shape":"fshape","fill":"solid","rotation":0,"mirror":false,"count":1}}'::jsonb, 'c', 'A alternativa correta é o F girado 180° (de cabeça para baixo). As outras quatro não podem ser obtidas apenas por rotação: todas exigem uma reflexão.', 'Discriminação entre rotação e reflexão (quiralidade).', 50, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Transformações geométricas conferidas; a figura F não possui simetria, então as 8 orientações (4 rotações × espelhamento) são distintas. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
