insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('esp-005', 1, 'pt-BR', 'espacial', 2, 'text', 'Um cubo grande de 3 × 3 × 3 é formado por 27 cubinhos iguais. A superfície externa do cubo grande é toda pintada. Quantos cubinhos têm EXATAMENTE duas faces pintadas?', null, null, 'c', 'Cubinhos com duas faces pintadas ficam no meio das arestas. Um cubo tem 12 arestas e cada uma tem 3 − 2 = 1 cubinho central: 12 × 1 = 12. (Os 8 dos vértices têm três faces pintadas; os 6 centros de face, uma.)', 'Visualização 3D com decomposição em vértices, arestas e faces.', 55, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Transformações geométricas conferidas; a figura F não possui simetria, então as 8 orientações (4 rotações × espelhamento) são distintas. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
