insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('esp-006', 1, 'pt-BR', 'espacial', 2, 'text', 'Em um dado comum de seis faces, as faces opostas sempre somam 7. O dado está sobre a mesa com a face 2 para cima e a face 3 voltada para você. Qual é a soma da face de baixo com a face de trás?', null, null, 'c', 'A face de baixo é oposta à de cima: 7 − 2 = 5. A de trás é oposta à da frente: 7 − 3 = 4. Soma: 5 + 4 = 9.', 'Relações de oposição em um objeto tridimensional.', 55, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Transformações geométricas conferidas; a figura F não possui simetria, então as 8 orientações (4 rotações × espelhamento) são distintas. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
