insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('esp-007', 1, 'pt-BR', 'espacial', 3, 'text', 'Um cubo grande de 4 × 4 × 4 é formado por 64 cubinhos iguais. A superfície externa do cubo grande é toda pintada. Quantos cubinhos NÃO têm nenhuma face pintada?', null, null, 'c', 'Os cubinhos sem tinta formam o núcleo interno, que tem (4 − 2) cubinhos em cada dimensão: 2 × 2 × 2 = 8.', 'Visualização do núcleo interno; distrator 27 corresponde a 3³.', 70, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Transformações geométricas conferidas; a figura F não possui simetria, então as 8 orientações (4 rotações × espelhamento) são distintas. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
