insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('esp-008', 1, 'pt-BR', 'espacial', 3, 'figure_choice', 'A figura-modelo é primeiro ESPELHADA da esquerda para a direita (como em um espelho colocado ao lado dela) e, em seguida, GIRADA 90° no sentido horário. Qual é o resultado?', null, '{"model":{"shape":"fshape","fill":"solid","rotation":0,"mirror":false,"count":1}}'::jsonb, 'b', 'Após o espelhamento, os braços do F passam a apontar para a esquerda. Girando 90° no sentido horário, a haste fica horizontal e os braços passam a apontar para cima. As alternativas com a haste horizontal e os braços para baixo correspondem a girar sem espelhar ou a girar no sentido anti-horário.', 'Composição de duas transformações (reflexão seguida de rotação).', 80, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Transformações geométricas conferidas; a figura F não possui simetria, então as 8 orientações (4 rotações × espelhamento) são distintas. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
