insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('log-001', 1, 'pt-BR', 'logico', 1, 'text', 'Ana é mais alta que Bia. Bia é mais alta que Carla. Quem é a mais baixa das três?', null, null, 'c', 'Ana > Bia > Carla, pela transitividade da relação ''mais alta que''. Carla é a mais baixa.', 'Inferência transitiva com três termos.', 30, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Todas as hipóteses testadas exaustivamente; solução única confirmada. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
