insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('log-002', 1, 'pt-BR', 'logico', 1, 'text', 'Quatro amigos — João, Kátia, Leo e Mia — sentam-se lado a lado em uma fila de 4 cadeiras numeradas de 1 a 4. João está na cadeira 1. Mia está na cadeira imediatamente seguinte à de João. Leo não está na cadeira 4. Quem está na cadeira 4?', null, null, 'b', 'João está na cadeira 1 e Mia na 2. Restam as cadeiras 3 e 4 para Leo e Kátia; como Leo não está na 4, ele está na 3 e Kátia na 4.', 'Problema de alocação com eliminação direta.', 45, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Todas as hipóteses testadas exaustivamente; solução única confirmada. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
