insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('log-003', 1, 'pt-BR', 'logico', 2, 'text', 'Sempre que chove, o chão do pátio fica molhado. Neste momento, o chão do pátio está seco. O que se pode concluir com certeza?', null, null, 'b', 'Pela contrapositiva (modus tollens): se chovesse agora, o chão estaria molhado; como está seco, não está chovendo agora. Não é possível afirmar nada sobre mais cedo, pois o chão pode ter secado.', 'Modus tollens com distrator que extrapola o intervalo temporal das premissas.', 50, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Todas as hipóteses testadas exaustivamente; solução única confirmada. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
