insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('log-004', 1, 'pt-BR', 'logico', 2, 'text', 'Cinco corredores terminaram uma prova, sem empates. Tiago chegou antes de Paulo, mas depois de Bruno. Diego chegou depois de Paulo. Ênio chegou em primeiro lugar. Quem chegou em terceiro lugar?', null, null, 'b', 'Ênio é o 1º. Das condições, Bruno < Tiago < Paulo < Diego na ordem de chegada. Os quatro ocupam as posições 2 a 5 nessa ordem: Bruno 2º, Tiago 3º, Paulo 4º, Diego 5º.', 'Ordenação linear com cadeia de restrições; solução única.', 60, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Todas as hipóteses testadas exaustivamente; solução única confirmada. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
