insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('log-005', 1, 'pt-BR', 'logico', 2, 'text', 'Considere a afirmação: "Se um número inteiro é múltiplo de 6, então ele é par." Qual das afirmações abaixo é necessariamente verdadeira?', null, null, 'c', 'A contrapositiva de ''se P então Q'' é ''se não Q então não P'', e é logicamente equivalente: se é ímpar, não é múltiplo de 6. As opções a e b são a recíproca e a inversa (inválidas: 4 é par e não é múltiplo de 6). A opção e é falsa: 12 é múltiplo de 6 e de 4.', 'Distingue contrapositiva de recíproca e inversa; afirmações conferidas com contraexemplos.', 55, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Todas as hipóteses testadas exaustivamente; solução única confirmada. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
