insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('log-006', 1, 'pt-BR', 'logico', 3, 'text', 'Três caixas fechadas estão rotuladas "Maçãs", "Laranjas" e "Mistas". Uma contém só maçãs, outra só laranjas e outra uma mistura das duas frutas — mas TODOS os rótulos estão errados. Você pode retirar, sem olhar, uma única fruta de uma única caixa. De qual caixa deve retirar a fruta para descobrir o conteúdo de todas as caixas?', null, null, 'c', 'A caixa rotulada "Mistas" não é mista, então contém só um tipo de fruta; a fruta retirada revela qual. Suponha que saia maçã: essa é a caixa de maçãs. A caixa rotulada "Laranjas" não pode ter laranjas nem maçãs (já identificadas), então é a mista; a rotulada "Maçãs" tem laranjas. O caso de sair laranja é simétrico.', 'Requer usar a restrição ''todos os rótulos errados'' para escolher a única fonte de informação conclusiva.', 75, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Todas as hipóteses testadas exaustivamente; solução única confirmada. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
