insert into public.question_options (question_id, option_id, position, text, figure) values ('log-006', 'b', 1, 'Da caixa rotulada "Laranjas"', null) on conflict (question_id, option_id) do nothing;
insert into public.question_options (question_id, option_id, position, text, figure) values ('log-006', 'c', 2, 'Da caixa rotulada "Mistas"', null) on conflict (question_id, option_id) do nothing;
insert into public.question_options (question_id, option_id, position, text, figure) values ('log-006', 'd', 3, 'De qualquer uma das três', null) on conflict (question_id, option_id) do nothing;
