insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('log-007', 1, 'pt-BR', 'logico', 3, 'text', 'Em uma ilha, cada habitante sempre diz a verdade ou sempre mente. Rui afirma: "Eu e Sara somos mentirosos." O que se pode concluir?', null, null, 'c', 'Se Rui dissesse a verdade, ele seria mentiroso — contradição. Logo, Rui mente e a frase é falsa: não é verdade que ambos mentem. Como Rui mente, Sara diz a verdade.', 'Raciocínio por redução ao absurdo; solução única.', 75, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Todas as hipóteses testadas exaustivamente; solução única confirmada. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
