insert into public.question_options (question_id, option_id, position, text, figure) values ('log-007', 'c', 2, 'Rui mente e Sara diz a verdade', null) on conflict (question_id, option_id) do nothing;
insert into public.question_options (question_id, option_id, position, text, figure) values ('log-007', 'd', 3, 'Rui diz a verdade e Sara mente', null) on conflict (question_id, option_id) do nothing;
