insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('log-008', 1, 'pt-BR', 'logico', 3, 'text', 'Exatamente uma entre três pessoas quebrou um vaso. Ana diz: "Foi o Beto." Beto diz: "Não fui eu." Caio diz: "Não fui eu." Sabe-se que exatamente uma das três frases é verdadeira. Quem quebrou o vaso?', null, null, 'c', 'Teste cada hipótese. Se foi Ana: frases de Beto e Caio verdadeiras (2 verdades). Se foi Beto: frases de Ana e Caio verdadeiras (2). Se foi Caio: apenas a frase de Beto é verdadeira (1). Logo, foi Caio.', 'Teste exaustivo de hipóteses com restrição de contagem.', 80, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Todas as hipóteses testadas exaustivamente; solução única confirmada. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
