insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('mem-001', 1, 'pt-BR', 'memoria', 1, 'memory', 'Qual era o TERCEIRO número da sequência?', '{"text":"7  2  9  4","exposureSeconds":6}'::jsonb, null, 'e', 'A sequência era 7, 2, 9, 4. O terceiro número é 9.', 'Retenção serial de 4 dígitos com recuperação por posição.', 30, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Procedimento: o estímulo é exibido uma única vez, por tempo fixo controlado pelo servidor, e só depois a pergunta aparece. Não é possível impedir anotações externas em ambiente on-line não supervisionado. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
