insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('prb-001', 1, 'pt-BR', 'problemas', 1, 'text', 'Uma reunião começa às 14h40 e dura 1 hora e 35 minutos. A que horas ela termina?', null, null, 'c', '14h40 + 1h = 15h40; 15h40 + 35 min = 16h15.', 'Aritmética de tempo em base sexagesimal.', 35, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Solução verificada por enumeração ou cálculo direto. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
