insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('prb-003', 1, 'pt-BR', 'problemas', 2, 'text', 'Um caracol está no fundo de um poço de 10 metros. A cada dia ele sobe 3 metros e, a cada noite, escorrega 2 metros. Em que dia ele chega ao topo do poço?', null, null, 'b', 'Ao fim de cada noite, ele avança 1 metro líquido. Após 7 noites, está a 7 metros. No 8º dia, sobe 3 metros e atinge 10 metros, saindo antes de escorregar.', 'Exige perceber que o último dia não é seguido de escorregão; distrator 10º dia vem de 10 ÷ 1.', 60, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Solução verificada por enumeração ou cálculo direto. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
