insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('prb-004', 1, 'pt-BR', 'problemas', 2, 'text', 'Seis pessoas se cumprimentam com um aperto de mão, e cada par de pessoas se cumprimenta exatamente uma vez. Quantos apertos de mão ocorrem no total?', null, null, 'b', 'Número de pares: 6 × 5 ÷ 2 = 15. Divide-se por 2 porque o aperto entre A e B é o mesmo que entre B e A.', 'Combinação de 6 elementos tomados 2 a 2; distrator 30 omite a divisão por 2.', 50, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Solução verificada por enumeração ou cálculo direto. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
