insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('prb-005', 1, 'pt-BR', 'problemas', 2, 'text', 'Um relógio adianta 2 minutos a cada hora. Ele foi acertado exatamente ao meio-dia. Que horário ele mostrará quando o horário correto for 18h?', null, null, 'd', 'Do meio-dia às 18h passam 6 horas; 6 × 2 = 12 minutos de adiantamento. O relógio mostrará 18h12.', 'Taxa constante ao longo do tempo; distrator 17h48 confunde adiantar com atrasar.', 50, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Solução verificada por enumeração ou cálculo direto. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
