insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('prb-006', 1, 'pt-BR', 'problemas', 2, 'text', 'Em um torneio de eliminação simples com 32 jogadores, cada partida elimina exatamente um jogador e não há empates. Quantas partidas são necessárias para definir o campeão?', null, null, 'b', 'Para restar 1 campeão, 31 jogadores precisam ser eliminados, e cada partida elimina exatamente 1. Conferência por rodadas: 16 + 8 + 4 + 2 + 1 = 31.', 'Problema resolvido por invariante; o cálculo por rodadas confirma.', 55, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Solução verificada por enumeração ou cálculo direto. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
