insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('prb-007', 1, 'pt-BR', 'problemas', 3, 'text', 'Um livro tem as páginas numeradas de 1 a 120. Quantas vezes o algarismo 7 aparece, ao todo, nessa numeração?', null, null, 'd', 'Na casa das unidades: 7, 17, 27, …, 117 → 12 ocorrências. Na casa das dezenas: 70 a 79 → 10 ocorrências. Total: 22 (o número 77 contribui com uma ocorrência em cada contagem, o que está correto, pois tem dois algarismos 7).', 'Contagem sistemática por posição; distrator 21 conta o 77 apenas uma vez.', 80, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Solução verificada por enumeração ou cálculo direto. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
