insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('prb-008', 1, 'pt-BR', 'problemas', 3, 'text', 'Há 9 moedas de aparência idêntica; uma delas é mais pesada que as outras, que têm todas o mesmo peso. Usando uma balança de dois pratos (sem pesos de referência), qual é o número mínimo de pesagens que GARANTE identificar a moeda mais pesada?', null, null, 'b', 'Divida em 3 grupos de 3 e compare dois grupos: o mais pesado, ou o que ficou de fora em caso de equilíbrio, contém a moeda. Repita com as 3 moedas desse grupo (compare 2 delas). Cada pesagem tem 3 resultados, e 3² = 9 cobre todos os casos; 1 pesagem distingue no máximo 3 casos, o que é insuficiente.', 'Problema de busca ternária; mínimo justificado pelo limite informacional.', 80, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Solução verificada por enumeração ou cálculo direto. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
