insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('qnt-001', 1, 'pt-BR', 'quantitativo', 1, 'text', 'Um produto custa R$ 80,00 e recebe 25% de desconto. Qual é o preço final?', null, null, 'b', '25% de 80 = 20. Preço final: 80 − 20 = R$ 60,00.', 'Porcentagem simples aplicada a desconto.', 35, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Cálculo conferido; unidades e arredondamentos explícitos. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
