insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('qnt-004', 1, 'pt-BR', 'quantitativo', 2, 'text', 'A média de 5 números é 12. Retirando-se um deles, a média dos 4 restantes passa a ser 10. Qual número foi retirado?', null, null, 'e', 'Soma dos 5 números: 5 × 12 = 60. Soma dos 4 restantes: 4 × 10 = 40. O número retirado é 60 − 40 = 20.', 'Relação entre média e soma.', 55, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Cálculo conferido; unidades e arredondamentos explícitos. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
