insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('qnt-005', 1, 'pt-BR', 'quantitativo', 2, 'text', 'Uma torneira enche um tanque sozinha em 6 horas; outra enche o mesmo tanque sozinha em 3 horas. Abertas juntas, em quanto tempo enchem o tanque vazio?', null, null, 'b', 'Em 1 hora, as torneiras enchem 1/6 + 1/3 = 1/6 + 2/6 = 1/2 do tanque. O tanque inteiro leva 2 horas.', 'Soma de taxas de trabalho; o distrator 4 h 30 min é a média aritmética dos tempos.', 60, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Cálculo conferido; unidades e arredondamentos explícitos. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
