insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('qnt-006', 1, 'pt-BR', 'quantitativo', 3, 'text', 'Em um grupo, 60% das pessoas falam inglês, 50% falam espanhol e 20% não falam nenhum desses dois idiomas. Qual porcentagem do grupo fala os dois idiomas?', null, null, 'c', 'Falam pelo menos um idioma: 100% − 20% = 80%. Pelo princípio da inclusão–exclusão: 60% + 50% − ambos = 80%, logo ambos = 30%.', 'Princípio da inclusão–exclusão com conjuntos.', 75, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Cálculo conferido; unidades e arredondamentos explícitos. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
