insert into public.questions (id, version, locale, category_id, difficulty, format, prompt, stimulus, figure, answer_option_id, explanation, rationale, recommended_seconds, status, active, tags, quality, irt) values ('qnt-007', 1, 'pt-BR', 'quantitativo', 3, 'text', 'Um carro percorre a primeira metade de um trajeto a 60 km/h e a segunda metade, de mesmo comprimento, a 40 km/h. Qual é a velocidade média no trajeto completo?', null, null, 'b', 'Considere 120 km no total: 60 km a 60 km/h levam 1 h; 60 km a 40 km/h levam 1,5 h. Velocidade média = 120 km ÷ 2,5 h = 48 km/h (média harmônica, não aritmética).', 'Velocidade média com distâncias iguais; o distrator 50 km/h é a média aritmética.', 75, 'reviewed', true, '{}'::text[], '{"reviewStatus":"author_reviewed","reviewedAt":"2026-10-29","notes":"Cálculo conferido; unidades e arredondamentos explícitos. Sem calibração empírica.","empiricallyCalibrated":false}'::jsonb, null) on conflict (id) do nothing;
